export const NMAP_SCAN_TYPES = [
  { flag: "-sS", name: "TCP SYN Scan", aka: "Half-open scan", description: "Sends SYN packet; RST+ACK = closed, SYN+ACK = open (sends RST, never completes handshake). Default for root. Fast and stealthy — most firewalls log completed connections, not half-open.", requires_root: true, speed: "fast", stealth: "high", example: "nmap -sS 192.168.1.0/24", output_states: ["open", "closed", "filtered"] },
  { flag: "-sT", name: "TCP Connect Scan", aka: "Full connect scan", description: "Uses the OS connect() syscall to complete the full TCP handshake. Default for unprivileged users. Slower and logged by most services, but works without raw packet privileges.", requires_root: false, speed: "medium", stealth: "low", example: "nmap -sT 192.168.1.1", output_states: ["open", "closed"] },
  { flag: "-sU", name: "UDP Scan", description: "Sends empty UDP packets (or protocol-specific payloads for known ports). Open ports rarely respond; closed ports send ICMP port unreachable. Very slow due to rate limiting of ICMP responses.", requires_root: true, speed: "very slow", stealth: "medium", example: "nmap -sU -T4 --top-ports 100 192.168.1.1", output_states: ["open", "open|filtered", "closed"] },
  { flag: "-sA", name: "TCP ACK Scan", description: "Sends ACK packets. Cannot determine open vs closed — only whether ports are filtered (no response or ICMP unreachable) vs unfiltered (RST response). Used to map firewall rulesets.", requires_root: true, speed: "fast", stealth: "medium", example: "nmap -sA 192.168.1.1", output_states: ["unfiltered", "filtered"] },
  { flag: "-sW", name: "TCP Window Scan", description: "Like ACK scan but examines the TCP window size of RST packets. Some implementations use positive window sizes for open ports and zero for closed. OS-dependent and unreliable.", requires_root: true, speed: "fast", stealth: "medium", example: "nmap -sW 192.168.1.1", output_states: ["open", "closed", "filtered"] },
  { flag: "-sM", name: "TCP Maimon Scan", description: "Sends FIN/ACK probe. Named after researcher Uriel Maimon who discovered that some BSD-derived systems drop the packet for open ports instead of responding with RST. Rarely works on modern systems.", requires_root: true, speed: "fast", stealth: "high", example: "nmap -sM 192.168.1.1", output_states: ["open|filtered", "closed"] },
  { flag: "-sN", name: "TCP Null Scan", description: "Sends TCP packet with no flags set. RFC 793 says closed ports respond with RST; open ports should drop it silently. Bypasses some non-stateful firewalls. Does not work against Windows (sends RST regardless).", requires_root: true, speed: "fast", stealth: "high", example: "nmap -sN 192.168.1.1", output_states: ["open|filtered", "closed"] },
  { flag: "-sF", name: "TCP FIN Scan", description: "Sends TCP packet with only FIN flag. Similar logic to Null scan — closed ports send RST, open ports silently drop. Evades some packet filters that only check SYN. Ineffective against Windows.", requires_root: true, speed: "fast", stealth: "high", example: "nmap -sF 192.168.1.1", output_states: ["open|filtered", "closed"] },
  { flag: "-sX", name: "TCP Xmas Scan", description: "Sends TCP packet with FIN, PSH, and URG flags set (lit up like a Christmas tree). Same RFC 793 logic as Null/FIN. Evades simple packet filters. Does not work against Windows or Cisco IOS.", requires_root: true, speed: "fast", stealth: "high", example: "nmap -sX 192.168.1.1", output_states: ["open|filtered", "closed"] },
  { flag: "-sI", name: "Idle Scan", aka: "Zombie scan", description: "Completely blind scan using a zombie host's IP ID sequence. Spoofs packets from zombie to target; checks zombie's IP ID increment to infer port state. The ultimate in stealth — no packets from your real IP reach the target.", requires_root: true, speed: "slow", stealth: "maximum", example: "nmap -sI zombie.example.com 192.168.1.1", output_states: ["open", "closed|filtered"] },
  { flag: "-sO", name: "IP Protocol Scan", description: "Determines which IP protocols (TCP, UDP, ICMP, IGMP, etc.) are supported by the target. Cycles through protocol numbers. ICMP protocol unreachable = not supported.", requires_root: true, speed: "medium", stealth: "medium", example: "nmap -sO 192.168.1.1", output_states: ["open", "closed", "filtered"] },
  { flag: "-sn", name: "Ping Scan", aka: "Host discovery only", description: "Disables port scanning; only performs host discovery. Sends ICMP echo, TCP SYN to 443, TCP ACK to 80, and ICMP timestamp. Useful for mapping live hosts on a network.", requires_root: false, speed: "very fast", stealth: "low", example: "nmap -sn 192.168.1.0/24", output_states: ["up", "down"] },
  { flag: "-sV", name: "Version Detection", description: "Probes open ports to determine service/version info. Sends protocol-specific probes and matches responses against nmap-service-probes database. Essential for accurate vulnerability assessment.", requires_root: false, speed: "slow", stealth: "low", example: "nmap -sV --version-intensity 5 192.168.1.1", output_states: ["open"] },
  { flag: "-sC", name: "Script Scan", aka: "Default scripts", description: "Runs the default category of NSE scripts. Equivalent to --script=default. Includes safe, useful scripts for service detection, enumeration, and basic vulnerability checks.", requires_root: false, speed: "medium", stealth: "low", example: "nmap -sC 192.168.1.1", output_states: ["open"] },
  { flag: "-O", name: "OS Detection", description: "Enables OS fingerprinting. Sends TCP/UDP/ICMP probes and matches responses against nmap-os-db. Requires at least one open and one closed port. Results include OS family, generation, and CPE.", requires_root: true, speed: "medium", stealth: "low", example: "nmap -O --osscan-guess 192.168.1.1", output_states: [] },
  { flag: "-A", name: "Aggressive Scan", description: "Enables OS detection (-O), version detection (-sV), script scanning (-sC), and traceroute (--traceroute) in one flag. Comprehensive but noisy and slow.", requires_root: true, speed: "slow", stealth: "very low", example: "nmap -A 192.168.1.1", output_states: [] },
  { flag: "-b", name: "FTP Bounce Scan", description: "Uses FTP bounce attack (PORT command) to scan ports via an FTP server. Exploits a feature of older FTP servers that allow connections to arbitrary hosts. Mostly patched in modern FTP.", requires_root: false, speed: "slow", stealth: "high", example: "nmap -b ftp.vuln.example.com 192.168.1.1", output_states: ["open", "closed"] },
  { flag: "--scanflags", name: "Custom TCP Scan", description: "Allows setting arbitrary TCP flag combinations. You can specify flags by name (URG, ACK, PSH, RST, SYN, FIN) or as a numeric value. For advanced firewall evasion and research.", requires_root: true, speed: "fast", stealth: "varies", example: "nmap --scanflags SYNFIN 192.168.1.1", output_states: ["varies"] },
  { flag: "-sY", name: "SCTP INIT Scan", description: "SCTP equivalent of TCP SYN scan. Sends INIT chunk; INIT-ACK = open, ABORT = closed. SCTP is used in telecom (SS7/Diameter). Many firewalls don't inspect SCTP traffic.", requires_root: true, speed: "fast", stealth: "high", example: "nmap -sY -p 2905,3868 192.168.1.1", output_states: ["open", "closed", "filtered"] },
  { flag: "-sZ", name: "SCTP Cookie Echo Scan", description: "Sends SCTP COOKIE-ECHO chunk. Open ports silently drop it; closed ports respond with ABORT. Like TCP FIN scan equivalent for SCTP. Evades SCTP-aware firewalls that only filter INIT.", requires_root: true, speed: "fast", stealth: "high", example: "nmap -sZ -p 2905 192.168.1.1", output_states: ["open|filtered", "closed"] },
];

export const NMAP_HOST_DISCOVERY = [
  { flag: "-sn", description: "Ping scan — disable port scan (formerly -sP)", example: "nmap -sn 10.0.0.0/24" },
  { flag: "-Pn", description: "Treat all hosts as online — skip host discovery", example: "nmap -Pn 10.0.0.1" },
  { flag: "-PS", description: "TCP SYN discovery on specified ports (default 80)", example: "nmap -PS22,80,443 10.0.0.0/24" },
  { flag: "-PA", description: "TCP ACK discovery on specified ports (default 80)", example: "nmap -PA80,443 10.0.0.0/24" },
  { flag: "-PU", description: "UDP discovery on specified ports (default 40125)", example: "nmap -PU53,161 10.0.0.0/24" },
  { flag: "-PY", description: "SCTP INIT discovery on specified ports", example: "nmap -PY22,80 10.0.0.0/24" },
  { flag: "-PE", description: "ICMP echo request discovery", example: "nmap -PE 10.0.0.0/24" },
  { flag: "-PP", description: "ICMP timestamp request discovery", example: "nmap -PP 10.0.0.0/24" },
  { flag: "-PM", description: "ICMP address mask request discovery", example: "nmap -PM 10.0.0.0/24" },
  { flag: "-PO", description: "IP protocol ping (sends packets with specified IP protocol)", example: "nmap -PO1,2,4 10.0.0.0/24" },
  { flag: "-PR", description: "ARP discovery on local network (default for local subnets)", example: "nmap -PR 192.168.1.0/24" },
  { flag: "--traceroute", description: "Trace hop path to each host", example: "nmap --traceroute 10.0.0.1" },
  { flag: "-n", description: "Never do DNS resolution (speeds up scanning)", example: "nmap -n 10.0.0.0/24" },
  { flag: "-R", description: "Always resolve DNS (even for down hosts)", example: "nmap -R 10.0.0.0/24" },
  { flag: "--dns-servers", description: "Specify custom DNS servers", example: "nmap --dns-servers 8.8.8.8,1.1.1.1 example.com" },
  { flag: "--system-dns", description: "Use OS DNS resolver instead of nmap's", example: "nmap --system-dns example.com" },
  { flag: "-iL", description: "Read target hosts from a file (one per line)", example: "nmap -iL targets.txt" },
  { flag: "-iR", description: "Choose random targets", example: "nmap -iR 100 -p 80" },
  { flag: "--exclude", description: "Exclude hosts/networks from scan", example: "nmap 10.0.0.0/24 --exclude 10.0.0.1,10.0.0.254" },
  { flag: "--excludefile", description: "Exclude hosts listed in file", example: "nmap 10.0.0.0/24 --excludefile no-scan.txt" },
];

