export const NMAP_EVASION = [
  { flag: "-f", description: "Fragment packets — split TCP header across multiple IP fragments (8 bytes each). Evades simple packet filters that don't reassemble.", example: "nmap -f 192.168.1.1" },
  { flag: "-f -f", description: "Double fragmentation — 16-byte fragments. Even smaller pieces for harder reassembly.", example: "nmap -f -f 192.168.1.1" },
  { flag: "--mtu", description: "Set custom MTU (must be multiple of 8). Control fragment sizes precisely.", example: "nmap --mtu 24 192.168.1.1" },
  { flag: "-D", description: "Decoy scan — cloak scan with decoys. Target sees scans from multiple IPs including yours. Use RND for random decoys, ME for your position.", example: "nmap -D RND:10,ME 192.168.1.1" },
  { flag: "-S", description: "Spoof source IP address. Requires sniffing the response by other means (or use -e to specify the interface).", example: "nmap -S 10.0.0.99 -e eth0 -Pn 192.168.1.1" },
  { flag: "--source-port", description: "Spoof source port number. Use 53 (DNS), 67 (DHCP), 88 (Kerberos) — often allowed through firewalls.", example: "nmap --source-port 53 192.168.1.1" },
  { flag: "-g", description: "Alias for --source-port", example: "nmap -g 53 192.168.1.1" },
  { flag: "--data-length", description: "Append random data to packets to avoid matching IDS signatures that check packet length.", example: "nmap --data-length 25 192.168.1.1" },
  { flag: "--data-string", description: "Append custom ASCII string to packets.", example: "nmap --data-string 'hello' 192.168.1.1" },
  { flag: "--data", description: "Append custom hex data to packets.", example: "nmap --data 0xdeadbeef 192.168.1.1" },
  { flag: "--ip-options", description: "Set IP options (loose/strict source routing, record route, timestamp).", example: "nmap --ip-options 'L 10.0.0.1 10.0.0.2' 192.168.1.1" },
  { flag: "--ttl", description: "Set IP time-to-live. Use to probe network topology or evade some filters.", example: "nmap --ttl 64 192.168.1.1" },
  { flag: "--randomize-hosts", description: "Randomize target host scan order. Makes scan less obvious in logs.", example: "nmap --randomize-hosts 192.168.1.0/24" },
  { flag: "--spoof-mac", description: "Spoof MAC address. Use vendor prefix, specific address, or 0 for random.", example: "nmap --spoof-mac Apple 192.168.1.1" },
  { flag: "--proxies", description: "Relay connections through HTTP/SOCKS4 proxy chain.", example: "nmap --proxies socks4://proxy:1080 192.168.1.1" },
  { flag: "--badsum", description: "Send packets with invalid TCP/UDP checksums. Hosts respond to bad checksums but many firewalls/IDS don't validate and silently drop.", example: "nmap --badsum 192.168.1.1" },
  { flag: "--adler32", description: "Use Adler32 instead of CRC32c for SCTP checksums.", example: "nmap --adler32 -sY 192.168.1.1" },
];

